import { TARGET_NAMES as SKILL_TARGET_NAMES } from "bitfab-flow";
import { AGENT_TYPES, agentForTarget, TARGET_NAMES as SESSION_TARGET_NAMES, } from "bitfab-lib/agent-hosts";
import { describe, expect, it } from "vitest";
describe("skill targets and chat session agents", () => {
    it("render skills for exactly the hosts that capture chat sessions", () => {
        expect([...SKILL_TARGET_NAMES].sort()).toEqual([...SESSION_TARGET_NAMES].sort());
    });
    it("give every skill target a chat session agent", () => {
        expect(SKILL_TARGET_NAMES.map(agentForTarget).sort()).toEqual([...AGENT_TYPES].sort());
    });
});
